// canary world rule — the pack's own manifest still declares the two-scope-
// dispatch-plus-skill-mounting shape RULES.md's "Keep the local pack loading"
// bullet requires, not just that pack.mjs and RULES.md exist on disk (that
// part is pack-intact.mjs's job, gated on the change touching this dir).
//
// A LIVENESS PROBE, not an opinion — an emptied `worldRules`/`workRules`/
// `skills` array is not a config error the pack loader would catch (the
// manifest still parses), so a session that drains one silently proves
// nothing next rehearsal even though the pack still "loads". This is the
// half of canon #555's shape a load-time parse can't see: the arrays and the
// skill files they name have to actually agree with what's on disk.
//
// Reads pack.mjs as text rather than importing it, so this stays a plain
// scan like its siblings: no module side effects, no dependency on the
// runner's cwd resolving the sibling import correctly.
//
// Dependency-free: plain finding objects, no imports out of `.claudinite/shared/`.
const id = 'canary/pack-shape';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the manifest parse, two-scope dispatch and skill mounting this pack proves are only proven while pack.mjs ' +
  'actually declares a rule in each scope and every skill it names is on disk';

const DIR = '.claudinite/local/packs/canary/';
const PACK_FILE = `${DIR}pack.mjs`;
const SKILLS_DIR = `${DIR}skills/`;

function arrayBody(text, key) {
  const m = new RegExp(`${key}:\\s*\\[([^\\]]*)\\]`).exec(text);
  return m ? m[1].trim() : null;
}

export default {
  id,
  severity,
  description: 'pack.mjs declares at least one rule per scope and one skill, and every declared skill exists on disk',
  doc,
  why,

  run(ctx) {
    const text = ctx.read(PACK_FILE);
    if (text === null) return []; // pack-intact.mjs already covers a missing manifest

    const out = [];
    const flag = (what, fix) => out.push({ rule: id, severity, file: PACK_FILE, line: null, what, why, fix, doc });

    const worldRules = arrayBody(text, 'worldRules');
    if (!worldRules) {
      flag('declares no worldRules', 'list at least one world-scope rule — an empty array proves nothing about world-scope dispatch');
    }
    const workRules = arrayBody(text, 'workRules');
    if (!workRules) {
      flag('declares no workRules', 'list at least one work-scope rule — an empty array proves nothing about work-scope dispatch');
    }
    const skillsBody = arrayBody(text, 'skills');
    const skillNames = skillsBody ? [...skillsBody.matchAll(/['"]([^'"]+)['"]/g)].map((m) => m[1]) : [];
    if (skillNames.length === 0) {
      flag('declares no bundled skills', 'list at least one skill — an empty array proves nothing about skill mounting');
    }
    for (const name of skillNames) {
      const skillFile = `${SKILLS_DIR}${name}/SKILL.md`;
      if (!ctx.exists(skillFile)) {
        flag(`declares skill "${name}" but ${skillFile} is missing`, `add ${skillFile}, or drop "${name}" from pack.mjs's skills list`);
      }
    }
    return out;
  },
};

// canary world rule — the vendored mount is present and carries the engine's
// world-sweep entry point.
//
// This is a LIVENESS PROBE, not an opinion. If the pack loader ever stops
// discovering local packs, this rule stops running and the canary's world sweep
// goes quiet rather than red — so the rule is paired with the selftest, which
// asserts the rule was dispatched at all. What this rule itself catches is the
// other half: a converge that lands a declaration without the tree it declares.
//
// It can only fire when the mount is missing, and when the mount is missing the
// sweep could not have started from it — so in normal operation it never fires.
// That is the point: a canary rule that has opinions makes the canary red for
// reasons unrelated to the canon ref under test.
//
// Local-pack check modules are dependency-free on purpose: plain finding
// objects, no imports out of `.claudinite/shared/` — committed consumer code
// must not reach into the vendored canon (the `claudinite-isolation` rule
// enforces this), because that tree is refreshed nightly and refactored
// upstream.
const id = 'canary/mount-present';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the canary only means something while it is a real member — without the vendored mount ' +
  'a rehearsal against a canon ref proves nothing about consumers';

const ENTRY = '.claudinite/shared/engine/checks/check_the_world.mjs';

export default {
  id,
  severity,
  description: 'the vendored Claudinite mount is present at .claudinite/shared/',
  doc,
  why,

  run(ctx) {
    if (ctx.exists(ENTRY)) return [];
    return [{
      rule: id,
      severity,
      file: ENTRY,
      line: null,
      what: `${ENTRY} is missing — the vendored mount is absent or incomplete`,
      why,
      fix: 'run the canon\'s vendoring/apply-vendor-set.mjs against this repo to rebuild .claudinite/shared/',
      doc,
    }];
  },
};

// canary work rule — a session that edits the canary pack must leave it loadable.
//
// Work scope, so it judges the change in front of the session (the Stop hook),
// not the repo at rest: it only looks when the branch actually touched the pack
// directory. A session that never goes near it is never asked about it.
//
// Like its world-scope sibling this is a liveness probe with a real edge case
// attached — deleting `pack.mjs` or `RULES.md` while keeping the `local/canary`
// declaration turns every later session into a blocking `config` error at load,
// which is the least debuggable way for this repo to break. In normal operation
// it never fires; its job is to prove work-scope dispatch reached a local pack.
//
// Dependency-free by the same rule as the world-scope module: plain finding
// objects, no imports out of `.claudinite/shared/`.
const id = 'canary/pack-intact';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the declaration names local/canary — if the manifest or its prose goes missing the pack ' +
  'loader raises a blocking config error on every later session, in this repo and in every rehearsal of it';

const DIR = '.claudinite/local/packs/canary/';
const REQUIRED = [`${DIR}pack.mjs`, `${DIR}RULES.md`];

export default {
  id,
  severity,
  description: 'a change touching the canary pack leaves its manifest and prose in place',
  doc,
  why,
  scope: 'work',

  run(work) {
    if (!work.changedFiles.some((f) => f.startsWith(DIR))) return [];
    return REQUIRED.filter((f) => !work.exists(f)).map((file) => ({
      rule: id,
      severity,
      file,
      line: null,
      what: `${file} is gone, but .claudinite-checks.json still declares local/canary`,
      why,
      fix: `restore ${file}, or drop "local/canary" from the "packs" list in .claudinite-checks.json`,
      doc,
    }));
  },
};

// canary world rule — the artifacts that make this repo a realistic Claudinite
// member (beyond the vendored mount, covered by mount-present.mjs, and this
// pack's own manifest/prose, covered by pack-intact.mjs) are present.
//
// A LIVENESS PROBE, not an opinion — RULES.md's "Stay a realistic member" names
// the hooks config and the scheduler/conformance workflows alongside the mount
// and the pack; this is the part of that bullet no other check covers. It can
// only fire when this repo has quietly stopped carrying one of them, which in
// normal operation never happens — same non-firing-by-design shape as its
// siblings, so a real opinion never rides in here.
//
// Dependency-free: plain finding objects, no imports out of `.claudinite/shared/`.
const id = 'canary/realism-artifacts';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the canary only means something while it is a real member — without the hooks or the workflows a rehearsal ' +
  'against a candidate ref proves nothing about consumers';

const REQUIRED = [
  '.claude/settings.json',
  '.github/workflows/claudinite-scheduler.yml',
  '.github/workflows/claudinite-conformance.yml',
];

export default {
  id,
  severity,
  description: 'the hooks config and the scheduler/conformance workflows are present',
  doc,
  why,

  run(ctx) {
    return REQUIRED.filter((f) => !ctx.exists(f)).map((file) => ({
      rule: id,
      severity,
      file,
      line: null,
      what: `${file} is missing — this repo no longer carries a piece of what makes it a realistic Claudinite member`,
      why,
      fix: 'restore the file (from git history, or by re-running the canon\'s adoption/converge-wiring against this repo)',
      doc,
    }));
  },
};

[
  {
    "id": "claudinite-isolation",
    "severity": "blocking",
    "failureMessage": "the vendored canon is refreshed nightly and refactored upstream — code that reaches into it inherits every canon rename as a breaking change",
    "fix": "inline the few lines you need into your own tree, remove the reference, or accept it with a reason in .claudinite-settings.json (rule \"claudinite-isolation\")",
    "relevantWhen": { "pathExists": ".claudinite/shared" },
    "forbidReferences": [
      {
        "from": ".",
        "to": ".claudinite",
        "matchUniqueFilenames": false,
        "except": [".claudinite", ".claude", ".github/workflows", ".gitignore", ".gitattributes", "CLAUDE.md", ".claudinite-settings.json", ".claudinite-checks.json"],
        "reason": "consumer files must not couple to the vendored canon — the wiring files are the reviewed exceptions (vendoring/DESIGN.md)"
      }
    ]
  },
  {
    "id": "scheduler-workflow-shape",
    "severity": "blocking",
    "failureMessage": "the scheduler is the repo's only cron and its anchor arithmetic runs on the hour — a drifted cron or a missing guard silently breaks staggering, double-run safety, or manual runs",
    "scanFiles": ".github/workflows/claudinite-scheduler.yml",
    "countMatchingLines": [
      {
        "linesMatching": "/\\bcron:\\s/",
        "atLeast": 1,
        "atMost": 1,
        "what": "declares {count} cron schedules, expected exactly one",
        "fix": "keep a single cron — the scheduler is the repo's only one, and its two daily ticks are two hours in ONE expression, never two schedule entries"
      }
    ],
    "matchLines": [
      {
        "match": "/\\bcron:.*/",
        "unlessLineMatches": "/\\bcron:\\s*['\"]?(1[0-9]|[2-4][0-9]|50) (([0-9]|1[0-9]|2[0-3]),([0-9]|1[0-9]|2[0-3])|\\*) \\* \\* \\*['\"]?\\s*$/",
        "what": "{match} is not two daily ticks (or the legacy hourly form) on a fixed minute in :10\u2013:50",
        "fix": "use \"<minute> <dailyHour>,<dailyHour+12> * * *\", minute 10 to 50, all written by the converge; the legacy \"<minute> * * * *\" still passes until this repo's workflow pull request lands"
      }
    ],
    "checkEachFile": [
      {
        "require": "/^\\s*workflow_dispatch:/m",
        "what": "has no workflow_dispatch trigger",
        "fix": "add workflow_dispatch: so the scheduler can be run manually"
      },
      {
        "require": "/^\\s*concurrency:/m",
        "what": "has no concurrency group",
        "fix": "add a concurrency: group so overlapping runs serialize (double-run safety)"
      },
      {
        "require": "/engine\\/scheduler\\/queue\\/(scheduler-run|tick)\\.mjs/",
        "what": "does not run the vendored engine entry",
        "fix": "run the vendored engine entry — node .claudinite/shared/engine/scheduler/queue/scheduler-run.mjs, or the retired `tick.mjs` beside it until this repo's workflow pull request lands"
      },
      {
        "require": "/^\\s*contents:\\s*write\\b/m",
        "what": "does not grant contents: write",
        "fix": "set permissions.contents: write — the update runner pushes its delivery branch; without it the self-refresh 403s"
      },
      {
        "require": "/^\\s*pull-requests:\\s*write\\b/m",
        "what": "does not grant pull-requests: write",
        "fix": "set permissions.pull-requests: write — the update runner opens its PR and arms auto-merge; without it the PR create 403s"
      }
    ]
  },
  {
    "id": "claudinite-lifecycle-declared",
    "severity": "blocking",
    "failureMessage": "claudinite-lifecycle carries Claudinite's own rules — the mount, the declaration, adoption, the update and the task contract — a member that does not declare it runs the machinery with none of them",
    "checkParsedFiles": [
      {
        "file": ".claudinite-settings.json",
        "requireValueInArray": { "atField": "packs", "value": "claudinite-lifecycle", "matchingEntryObjectsByField": "id" },
        "what": "does not declare the mandatory \"claudinite-lifecycle\" pack",
        "fix": "add \"claudinite-lifecycle\" to \"packs\" — it is basics' own dependency, so the requires closure writes it back the next time the declaration is written"
      }
    ]
  }
]

