    // A local pack's id must equal its directory name. The convention gives it that
    // for free, so this can only fire on a manifest that OVERRODE the id — and the
    // override is exactly what must not be allowed here: the engine activates a pack
    // by its exported id, but the fleet planner reads a local pack's daily tasks by
    // directory name (it never imports pack.mjs), so a mismatch would silently
    // diverge — the engine runs the pack while the fleet skips its task.
    if (local && mod.id !== name) {
      errors.push({
        what: `the local pack in ${rel} exports id "${mod.id}" but its directory is "${name}"`,
        fix: `rename the directory to "${mod.id}", or set the pack's id to "${name}" — a local pack's id must match its directory name`,
        dir: packDir,
      });
      continue;
    }
    // A malformed `questions` manifest field is a load fault like any other —
    // reported here so the runner surfaces it pack-agnostically, no interview
    // import needed (the pack owns the interview HYGIENE check; the engine owns
    // the manifest-shape validation).
    for (const e of packQuestions(mod).errors) errors.push({ ...e, dir: packDir });
    // The rest of the manifest against the spec (pack-schema.mjs). REPORTED, not
    // fatal: a pack whose declaration is incomplete still loads and still runs
    // its checks — silently disabling a repo's own rules is a worse failure than
    // the one being reported, and the blocking config error is what gets it fixed.
    for (const e of validateManifest(mod, { label: `the pack in ${rel}`, skillDirs: bundledSkillDirs(packDir) })) {
      errors.push({ ...e, dir: packDir });
    }
    // The pack's declared checks (declared-checks.json — data, not a module) ride
    // its rule lists: discovered structurally like the pack itself, so a
    // declaration is added by writing it, with no manifest line to keep in sync.
    // A coded rule's scope is the list it sits in; a declaration has no list, so
    // its own `scope` picks the list it joins — and normalizeManifest stamps the
    // same answer back either way.
    const declared = await declaredChecksIn(packDir, rel, errors);
    // The pack's CODED rules, discovered the same way its declared ones already
    // were: `<pack>/worldRules/*.mjs` and `<pack>/workRules/*.mjs`, each module
    // default-exporting one rule. A manifest that declares the list overrides the
    // directory, exactly like every other convention — which is why the scan runs
    // only for a scope the manifest left unspoken.
    const scanned = {};
    for (const scope of RULE_DIRS) {
      if (mod[scope] !== undefined) continue;
      scanned[scope] = await ruleModulesIn(packDir, scope, rel, errors);
    }
    // A CANON pack's own id is canonicalized like a declared one. A member's mount
    // is replaced per pack and per version, so a repo can hold a pack DIRECTORY
    // renamed by a migration record while the `pack.mjs` inside it still carries the
    // old id — the tree is only rewritten once the canon ships a version above the
    // one that repo has. Read literally, that pack announces an id nothing declares
    // and goes inert, taking its checks, prose and tasks with it silently. A local
    // pack keeps its own id: that namespace is the repo's.
    //
    // The raw id rides along because that canonicalization is only safe once the
    // WHOLE tree is known — an absorbed pack's leftover directory maps onto a
    // survivor that is itself present, and discoverPacks below undoes the map for
    // exactly that case (#1186).
    const pack = { ...normalizeManifest({ ...mod,
      ...(local ? {} : { id: canonicalPackId(mod.id), rawId: mod.id }),
      worldRules: [...(mod.worldRules ?? scanned.worldRules ?? []), ...declared.filter((r) => r.scope !== 'work')],
      workRules: [...(mod.workRules ?? scanned.workRules ?? []), ...declared.filter((r) => r.scope === 'work')],
    }), dir: packDir, local };
    pack.skillChecks = await scanSkillChecks(packDir, errors);
    out.push(pack);
  }
  return out;
}

// A pack's skill-owned checks: any <pack>/skills/<skill>/checks.mjs (default
// export = an array of coded rules) plus its declared-checks.json (the same
// declaration format a pack's own carries). Isolated per skill; run gated by the
// owning pack being active, exactly like the pack's own rules — a skill is pack
// content, so its checks ride the pack's activation.
async function scanSkillChecks(packDir, errors) {
  const rules = [];
  const skillsRoot = join(packDir, 'skills');
  if (!existsSync(skillsRoot)) return rules;
  let names;
  try {
    names = readdirSync(skillsRoot, { withFileTypes: true })
      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
  } catch (e) {
    errors.push({ what: `${LOCAL_PACKS_SUBDIR} skills path is not a readable directory: ${e.message}`, fix: 'make the pack\'s skills/ a directory (or remove it)', dir: skillsRoot });
    return rules;
  }
  for (const name of names) {
    const skillDir = join(skillsRoot, name);
    rules.push(...await declaredChecksIn(skillDir, `the ${name} skill`, errors));
    const manifest = join(skillDir, 'checks.mjs');
    if (!existsSync(manifest)) continue;
    try {
      rules.push(...(await import(pathToFileURL(manifest).href)).default);
    } catch (e) {
      errors.push({ what: `local skill check ${name}/checks.mjs failed to load: ${e.message}`, fix: 'fix or remove the skill\'s checks.mjs', dir: skillDir });
    }
  }
  return rules;
}

// Discover every pack structurally — canon `packs/<name>/pack.mjs` always, plus a
// consumer's own `<localRoot>/.claudinite/local_packs/<name>/pack.mjs` when a
// localRoot is given (the repo under test / the session's project root). No

// WHAT A MEMBER'S SETTINGS FILE IS CALLED — the names alone, and nothing that
// touches a disk to find one.
//
// The names are split out from `settings-file.mjs` because one reader has no disk:
// the dashboard page runs this module in a browser, unbundled, and a single
// `node:` import anywhere in its graph fails the page's first module load
// (#1286). So the two halves live apart — the vocabulary here, the `existsSync`
// probe that picks between the names beside it — and `settings-file.mjs` re-exports
// everything below, which keeps it the one import every disk-side reader needs.
//
// THE RENAME (#1252). The file is `.claudinite-settings.json`. It was
// `.claudinite-checks.json` when checks were the only thing a member declared, and
// it has not been a file of checks for a long time: it carries the pack
// declaration, the scheduler anchor, the installed versions and the delivery
// override. The old name is still READ, everywhere, because a member's file is
// renamed by a migration record that converges on its own schedule — and until
// every member has run it, both names name the same file.
//
// The tolerance is the LEGACY half of a rename with a stated end: the cleanup that
// deletes it is gated on no member still carrying the old name, never on a date
// (#1252 Phase 3).

export const SETTINGS_FILE = '.claudinite-settings.json';

// Retired from what anything WRITES; still read while members carry it.
export const LEGACY_SETTINGS_FILE = '.claudinite-checks.json';

// Both names, newest first — the read order, so a member mid-rename that somehow
// holds both is read from the one the migration wrote. Exported for the cross-repo
// readers, which have no disk to probe and must try the paths in this order over
// the API.
export const SETTINGS_FILES = [SETTINGS_FILE, LEGACY_SETTINGS_FILE];

// Is this path one of the two settings-file names? For the scans that ask whether a
// changed file is the declaration, which must keep answering yes for a member that
// has not been renamed yet.
export const isSettingsFile = (path) => SETTINGS_FILES.includes(String(path ?? '').split('/').pop());

