945	function assertParsedShape(ctx, j, parsed) {
946	  const s = j.spec;
947	
948	  // The merged select-then-assert family: pick documents (one exact file, or
949	  // every tracked file matching), optionally quantify over the named entries
950	  // of the object at forEachEntryAtField, then run every declared assertion
951	  // against each selected base object. An absent or unparsable document
952	  // asserts nothing, as everywhere in the parsed family.
953	  for (const a of s.checkParsedFiles ?? []) {
954	    const paths = a.everyScannedFile ? scanPaths(ctx, j)
955	      : a.file !== undefined ? [a.file]
956	        : ctx.tracked.filter((f) =>
957	          a.filesMatching.test(f) && (!a.whereFileContains || a.whereFileContains.test(ctx.read(f) ?? '')));
958	    for (const path of paths) {
959	      const doc = parsed(path);
960	      if (doc == null) continue;
961	      let bases;
962	      if (a.forEachEntryAtField) {
963	        const entries = fieldAt(doc, a.forEachEntryAtField);
964	        if (!entries || typeof entries !== 'object' || Array.isArray(entries)) continue;
965	        bases = Object.entries(entries).filter(([, entry]) => entry && typeof entry === 'object');
966	        if (a.whereEntryFieldEquals) {
967	          bases = bases.filter(([, entry]) =>
968	            fieldAt(entry, a.whereEntryFieldEquals.field) === a.whereEntryFieldEquals.equals);
969	        }
970	      } else {
971	        bases = [[null, doc]];
972	      }
973	      for (const [entryName, base] of bases) {
974	        if (a.whenFieldPresent && fieldAt(base, a.whenFieldPresent) === undefined) continue;
