241	// The one outcome an issue's labels carry, as the canonical word ('done',
242	// 'delivered', 'obsolete') or null. Everything that tallies or renders outcomes
243	// decodes through here, so a spelling change is one map entry and not a sweep.
244	export function outcomeOf(issue) {
245	  // `statusesOn` rather than `statusOf`: a closed item's terminal write is its
246	  // outcome even when a park label stands beside it, and park precedence is a
247	  // question about LIVE items — what the queue may pick up — not about history.
248	  const worn = statusesOn(issue);
249	  for (const [status, word] of OUTCOME_WORDS) if (worn.includes(status)) return word;
250	  return hasLabel(issue, OUTCOME_DELIVERED) ? 'delivered' : null;
